package dev.agenttrust.core;
import java.time.Instant;import java.util.*;import java.util.function.Supplier;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.core.RowMapper;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class AuditPeriodExportReaderTest {
 private final DemoUser user=new DemoUser("viewer","unused",UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"viewer");
 @Test void changedCursorFailsBeforeDatabaseScope(){var runs=mock(RunService.class);var jdbc=mock(JdbcTemplate.class);var service=new AuditPeriodExport(runs,jdbc,new ObjectMapper());var p=AuditPeriod.parse("2026-11-03","2026-11-03","all","all","all");String token=AuditPeriodCursor.encode(new AuditCursor(user.organizationId(),user.projectId(),Instant.parse("2026-11-03T00:00:00Z"),UUID.randomUUID()),p);assertThrows(IllegalArgumentException.class,()->service.export(user,AuditPeriod.parse("2026-11-02","2026-11-03","all","all","all"),token));verifyNoInteractions(runs,jdbc);}
 @Test void exportSelectKeepsTenantActorAndUtcBoundsAsParameters(){var runs=mock(RunService.class);when(runs.scoped(eq(user),any())).thenAnswer(call->((Supplier<?>)call.getArgument(1)).get());var seen=new ArrayList<List<Object>>();var jdbc=new JdbcTemplate(){@Override public <T> List<T> query(String sql,RowMapper<T> mapper,Object... args){assertTrue(sql.endsWith("ORDER BY created_at DESC,id DESC LIMIT 251"));assertTrue(sql.contains("organization_id=? AND project_id=?"));assertTrue(sql.contains("created_at>=? AND created_at<?"));seen.add(Arrays.asList(args));return List.of();}};var p=AuditPeriod.parse("2026-11-03","2026-11-03",user.actorId().toString(),"all","all");var result=new AuditPeriodExport(runs,jdbc,new ObjectMapper()).export(user,p,null);assertEquals(5,seen.getFirst().size());assertEquals(user.organizationId(),seen.getFirst().get(0));assertEquals(user.projectId(),seen.getFirst().get(1));assertEquals(user.actorId(),seen.getFirst().get(2));assertEquals(java.sql.Timestamp.from(p.startInclusive()),seen.getFirst().get(3));assertEquals(java.sql.Timestamp.from(p.endExclusive()),seen.getFirst().get(4));assertEquals(false,result.get("signed"));assertEquals(false,result.get("currentDeploymentAuthority"));verify(runs).scoped(eq(user),any());verifyNoMoreInteractions(runs);}
}
